describe('D-11 rewrite with the reference forms Lean records', () => {
  const PLAIN = [
    block({ id: 'a1', type: 'ASSUMPTION', name: 'A1', rationale: 'r', lean: 'S.a1' }),
    'abbrev a1 : Prop := Good t',
    'axiom a1.holds : a1',
